  ('2df4aa06-d319-5af6-87e3-e682e2645bdc', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'easy',
   $q$The sound of middle C "arrived a moment late, like a guest who had stopped to take off a coat." What does this simile show?$q$, $q$[{"text":"Someone had left a coat inside the piano that blocked the strings.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The note was the loudest and clearest sound the piano could make.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Visitors kept arriving at the house while Luis was playing.","is_correct":false,"misconception_token":"misreads-target"},{"text":"The note sounded with a small, noticeable delay after the key was pressed.","is_correct":true}]$q$::jsonb, $q$The note sounded with a small, noticeable delay after the key was pressed.$q$, $q$A guest pausing to remove a coat arrives a little late, just as the note "arrived a moment late." The coat is part of the comparison, not something actually inside the piano.$q$, 'draft', '55e04f37-dcb7-5914-9a5b-d7401c418c67')
