values
  ('64d2212a-30f1-56cf-ad22-398efdcd4dbf', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'medium',
   $q$Luis's father says, "Mrs. Halvorsen called it vintage. I would have called it old." What difference between "vintage" and "old" is he pointing out?$q$, $q$[{"text":"Both mean not new, but \"vintage\" suggests charm and value while \"old\" sounds worn out.","is_correct":true},{"text":"\"Old\" sounds more valuable than \"vintage,\" so his word is kinder.","is_correct":false,"misconception_token":"reverses-connotation"},{"text":"\"Vintage\" means newer than \"old,\" so she was wrong about its age.","is_correct":false,"misconception_token":"confuses-denotation"},{"text":"\"Vintage\" refers only to wine, so she used the word incorrectly.","is_correct":false,"misconception_token":"too-narrow"}]$q$::jsonb, $q$Both mean not new, but "vintage" suggests charm and value while "old" sounds worn out.$q$, $q$The words share a denotation, but "vintage" carries a positive connotation that helps a seller, which is why his father says it is not the same "to the person selling it." "Old" is the plainer, less flattering word, not the kinder one.$q$, 'draft', '55e04f37-dcb7-5914-9a5b-d7401c418c67')
