values
  ('affaf6c9-7e3d-5129-b44b-c4cdc1f13d69', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'medium',
   $q$A frame that "needs a little love" might need brakes, tires and work. What is the effect of this euphemism on a buyer?$q$, $q$[{"text":"It makes a list of real repairs sound small, warm and easy to handle.","is_correct":true},{"text":"It tells the buyer the bike is in perfect condition and ready to ride.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It promises the buyer that the seller will finish the repairs first.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It warns the buyer clearly that the bike is unsafe and should be avoided.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$It makes a list of real repairs sound small, warm and easy to handle.$q$, $q$"A little love" makes serious work, such as "new brakes, new tires and an afternoon of work," sound minor and affectionate. A euphemism softens the problem rather than warning clearly, so the choice "It warns the buyer clearly that the bike is unsafe and should be avoided" reverses its purpose.$q$, 'draft', '5881a7d5-59e2-52c6-94a7-1ea9049b07d8')
