  ('bd973085-2acd-5c3c-9416-816cfd26aab8', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'medium',
   $q$Amara changes "stubborn" to "determined" on Biscuit's card. What does this change accomplish?$q$, $q$[{"text":"It describes the same strong will in a way that sounds like a positive trait.","is_correct":true},{"text":"It makes Biscuit sound more difficult so that only experts will adopt him.","is_correct":false,"misconception_token":"reverses-connotation"},{"text":"It hides the fact that Biscuit is a dog and makes him sound like a cat.","is_correct":false,"misconception_token":"misreads-target"},{"text":"It tells visitors that Biscuit has completely stopped resisting commands.","is_correct":false,"misconception_token":"too-extreme"}]$q$::jsonb, $q$It describes the same strong will in a way that sounds like a positive trait.$q$, $q$"Stubborn" and "determined" share a meaning, but "determined" carries a positive connotation, fitting her wish not "to hide the truth" while showing the dog she knows. She keeps the meaning, so she is not claiming he stopped resisting entirely.$q$, 'draft', '2e36ce9a-2dca-5cff-a90b-752aeb4ce2be')
