values
  ('46f0f173-c46f-53e1-9946-b317029b0d5c', null, (select id from public.skills where slug = 'read-g10-figurative-language'), null, 'medium',
   $q$People came to treat ice "as a necessity rather than a luxury." Why is this contrast important to the passage?$q$, $q$[{"text":"It shows that ice remained an expensive treat that few people could afford.","is_correct":false,"misconception_token":"reverses-connotation"},{"text":"It shows that the ice trade failed because ice was too ordinary to sell.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It shows how completely the merchant changed people's view of ice from optional to essential.","is_correct":true},{"text":"It shows that people needed ice for medicine more than for drinks.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It shows how completely the merchant changed people's view of ice from optional to essential.$q$, $q$A luxury is something nice but optional, while a necessity is something people feel they cannot do without, so the contrast measures his success in creating demand. The passage never says ice stayed a rare treat; it says the opposite.$q$, 'draft', 'a64d80fc-e58f-572f-aac4-f572782d3a6c')
