  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('c3eb519a-f312-5f91-95e8-cd397402fba5', null, (select id from public.skills where slug = 'read-g10-literary-structure-pov'), null, 'hard',
   $q$How does the author's choice to tell the story from Sun-hee's limited perspective make the ending possible?$q$, $q$[{"text":"Readers know only what she knows, so they share her belief that she lost until the scoreboard reveals the truth.","is_correct":true},{"text":"Readers know what every runner is thinking, so they understand early that the qualifying time matters most.","is_correct":false,"misconception_token":"confuses-first-third-person"},{"text":"Readers know only what the volunteer knows, so they see the scoreboard before Sun-hee reaches it.","is_correct":false,"misconception_token":"wrong-narrator"},{"text":"Readers know only what the coach knows, so they learn the splits that Sun-hee could not hear.","is_correct":false,"misconception_token":"wrong-narrator"}]$q$::jsonb, $q$Readers know only what she knows, so they share her belief that she lost until the scoreboard reveals the truth.$q$, $q$Because the story stays inside Sun-hee's view (she cannot even hear her coach's splits), readers think she lost when she does, and the scoreboard surprises both. The narration never enters other runners' minds.$q$, 'draft', 'b14140a3-74a6-52ca-8677-968b3cb4f4c0')
