  ('ad37218e-40ae-5a89-8b10-d28643b07499', null, (select id from public.skills where slug = 'read-g10-literary-structure-pov'), null, 'medium',
   $q$How do the speaker's feelings about being "the bridge" develop in the fourth stanza?$q$, $q$[{"text":"The speaker feels confused about the meaning of a bridge and asks the father to explain it.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The speaker feels only resentment and refuses to help the father ever again.","is_correct":false,"misconception_token":"too-narrow"},{"text":"The speaker feels both pride in this power and a wish to be an ordinary teenager without that responsibility.","is_correct":true},{"text":"The speaker feels only pride and hopes to become a professional interpreter as an adult.","is_correct":false,"misconception_token":"too-narrow"}]$q$::jsonb, $q$The speaker feels both pride in this power and a wish to be an ordinary teenager without that responsibility.$q$, $q$"Some days I am proud" and "Some days I want to stand on the other side" express mixed feelings. Choosing only pride or only resentment ignores half of the stanza.$q$, 'draft', 'ba38fac0-98d2-578f-91aa-780c67c15e31')
