values
  ('84a1eafd-10dc-527a-8a20-bb3ef57f1ab2', null, (select id from public.skills where slug = 'read-g10-literary-structure-pov'), null, 'easy',
   $q$How is this passage structured?$q$, $q$[{"text":"A fable about a heron is placed inside a frame story about a grandmother telling it.","is_correct":true},{"text":"Two unrelated stories are placed side by side without any connection between them.","is_correct":false,"misconception_token":"misses-pattern"},{"text":"A fable about a heron is told by the heron herself, looking back on her life.","is_correct":false,"misconception_token":"wrong-narrator"},{"text":"A single story is told in reverse order, from the old heron back to the farmer.","is_correct":false,"misconception_token":"reverses-sequence"}]$q$::jsonb, $q$A fable about a heron is placed inside a frame story about a grandmother telling it.$q$, $q$The narrator describes the grandmother's yearly telling, and the heron fable sits inside that frame. The final paragraph connects the two, so they are not unrelated.$q$, 'draft', 'cf39a7c7-5f49-5b95-86ec-fb50ce48488b')
