-- Passage rg10-story-details-inference-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('37d0465c-8de8-515d-8f30-327b0ed629e5', 'rg10-story-details-inference-p06', (select id from public.skills where slug = 'read-g10-story-details-inference'), null,
        '9-12', $q$Alterations$q$, $q$My grandfather keeps his shop on Delancey Row
between a shoe repair and a small bakery.
The sign says ALTERATIONS in letters that were gold
before I was born. Now they are the color of tea.

He works at a black machine older than my mother.
It has a wheel he turns by hand to start each seam,
the way you might nudge a sleeping dog.
Then his foot finds the pedal and the needle runs.

People bring him trousers too long, sleeves too wide,
a graduation suit from a cousin who has moved away.
He pins them while they stand on the low wooden box,
his mouth full of pins, so he never says much.

Last spring I asked why he does not buy a new machine.
He held up a jacket, turned it inside out,
and showed me the seams, each stitch as even as a ruler.
He said, "Find me a new one that can do this," and went back to work.

This fall the bakery became a phone store.
The shoe repair has a sign that says FOR LEASE.
My grandfather still turns the wheel each morning
and waits, with his pins, for the bell above the door.

On Saturdays now I sit on the low wooden box.
He has started showing me how to thread the needle,
how to hold the fabric flat, how to listen
for the change in sound that means a seam is going wrong.$q$, 'draft')
