  ('097b97f8-0537-5992-972e-26e395074f14', null, (select id from public.skills where slug = 'read-g10-story-details-inference'), null, 'hard',
   $q$Which inference about the final stanza is best supported by details from the whole poem?$q$, $q$[{"text":"He teaches the speaker because so many customers arrive that he needs help.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He teaches the speaker because the speaker asked to be paid for Saturday work.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"He hopes to pass on his craft as the shops around his are closing.","is_correct":true},{"text":"He teaches the speaker so that he can finally retire and sell the old machine.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$He hopes to pass on his craft as the shops around his are closing.$q$, $q$He "has started" teaching right after the stanza about the closing shops, and he passes on fine skills such as listening for a seam going wrong. He still "waits" for customers and defends his old machine, so neither a flood of work nor selling the machine fits.$q$, 'draft', '37d0465c-8de8-515d-8f30-327b0ed629e5')
