values
  ('b86e5cad-5322-54e8-a2fb-5b15cb389898', null, (select id from public.skills where slug = 'read-g10-theme-summary'), null, 'medium',
   $q$How does the fourth stanza, which describes letting go of the baton, develop the theme?$q$, $q$[{"text":"It shows that the speaker's part of the success requires trusting someone else to finish it.","is_correct":true},{"text":"It shows that the speaker is afraid of running and wants to quit the team.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It suggests that the speaker disagrees with the rules about passing the baton.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It proves that the speaker is a faster runner than Marisol over any distance.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It shows that the speaker's part of the success requires trusting someone else to finish it.$q$, $q$Letting go is "harder than the running" because the speaker must release the baton "before I know if it will land," trusting a teammate. Nothing suggests the speaker wants to quit; the difficulty is about trust, not fear of running.$q$, 'draft', '867c859c-b4a3-5d8e-928b-72a4870b9830')
