values
  ('09404d1b-2145-59fb-a139-b092cf8b75a6', null, (select id from public.skills where slug = 'read-g10-theme-summary'), null, 'medium',
   $q$What does the description of the wind seeming to "pass straight through" the kite after the string breaks show?$q$, $q$[{"text":"That without the string, the kite cannot use the wind to stay up.","is_correct":true},{"text":"That the wind suddenly stopped blowing across the meadow.","is_correct":false,"misconception_token":"literal-reading"},{"text":"That the kite had climbed higher than the wind could reach.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"That the sparrow had warned the kite this would happen.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$That without the string, the kite cannot use the wind to stay up.$q$, $q$The same wind that "held it so steadily" no longer lifts the kite once nothing anchors it, which is the core of the theme. The wind is still there; the change is in the kite, so the wind did not stop.$q$, 'draft', '22ab2113-ca53-5255-9921-de940cc475f3')
