-- Passage rg10-theme-summary-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f34a3c20-71b8-55e0-971c-23ba0630eb73', 'rg10-theme-summary-p05', (select id from public.skills where slug = 'read-g10-theme-summary'), null,
        '9-12', $q$Map of Our Town, 1890$q$, $q$In the library basement, under glass,
our town is smaller than my hand.
The ink has faded to the color of weak tea.
Main Street is there, but it is called Mill Road,
and a blue line runs beside it
that I have never seen.

The archivist tells me it was Alder Creek.
They covered it with stone in 1931
and paved the road on top.
It still runs, she says. It runs under the bank,
under the bus stop, under the shoe store,
all the way down to the river in the dark.

I find the ferry landing where the parking garage stands.
I find a schoolhouse where the gas station sells ice.
I find a name I know, Okonkwo, printed small
beside a square that must have been a farm.
My neighbor still has that name.
I wonder if she knows about the square.

On the walk home I do not look at the stores.
I look at the curbs, the drains, the low places.
At the corner by the bank
I stop above an iron grate and listen.
Under the traffic, under the music from a passing car,
something is moving water toward the river.
It has been doing that the whole time.$q$, 'draft')
