-- Passage rg10-theme-summary-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('576c8f54-4019-50d7-a1f0-4eae061a95b0', 'rg10-theme-summary-p08', (select id from public.skills where slug = 'read-g10-theme-summary'), null,
        '9-12', $q$The Dark Field$q$, $q$The dark-sky park was two hours from the city, at the end of a gravel road with no streetlights. Ana Ferreira had promised her younger brother, Davi, that he would see the Milky Way. When they climbed out of the car, he looked up and frowned.

"There's barely anything," he said. "It looks like home."

He switched on his phone's flashlight to find the blanket in the trunk, then left it on to check the star chart he had downloaded. Each time he glanced up from the bright screen, the sky seemed emptier.

A ranger walking the field with a red-filtered lamp stopped beside them. She introduced herself as Ranger Akosua Boateng and asked how long they had been there.

"Ten minutes," Ana said.

"Then you've seen about a tenth of it," the ranger said. "Your eyes need close to half an hour to adjust to the dark. Every time you look at a white light, you start the clock over." She held up her lamp. "That's why this is red. It lets you see the ground without undoing the wait."

Davi sighed, but he turned off the phone and lay back on the blanket. For a while, there was nothing to do. A breeze moved through the grass. Somewhere far away, a car door closed. Ana counted the stars she could see and got to fifteen.

Then, slowly, it was not fifteen. Faint points appeared between the bright ones, and then points between those. A pale band began to spread from one side of the sky to the other, like breath on cold glass.

Davi sat up. "Was that there all along?"

"All along," the ranger said from somewhere in the dark.

On the drive home, Davi kept his phone in his pocket. He spent most of the ride looking out the window at the lights of the towns as they came closer, as though trying to remember what was behind them.$q$, 'draft')
