  ('7d72eb13-7038-585a-bc1d-c6c189f0d753', null, (select id from public.skills where slug = 'read-g10-word-parts'), null, 'easy',
   $q$The root bene means "good" or "well," fact means "do," and -or means "one who." Who is the "benefactor" in the passage?$q$, $q$[{"text":"A person who copied old letters by hand","is_correct":false,"misconception_token":"confuses-characters"},{"text":"A person who gave a gift to help the library","is_correct":true},{"text":"A person who borrowed books from the library","is_correct":false,"misconception_token":"ignores-root-clues"},{"text":"A person who complained about library costs","is_correct":false,"misconception_token":"opposite-meaning"}]$q$::jsonb, $q$A person who gave a gift to help the library$q$, $q$A benefactor is "one who does good," and this one "donated a brick building on Main Street." The neighbors who complained about money did the opposite of supporting the library.$q$, 'draft', 'edfad48f-1897-5b29-a6df-497e5fa046bb')
