  ('155bd14b-4666-578c-8720-d1bf1d5610f5', null, (select id from public.skills where slug = 'read-g11-argument-evidence'), null, 'hard',
   $q$Which statement best evaluates Morrow's argument about the two neighboring towns?$q$, $q$[{"text":"It is weak because the towns later regretted choosing railroads.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It is weak because other towns' choices do not show which option suits Brennick.","is_correct":true},{"text":"It is strong because it relies on actual votes rather than cost estimates.","is_correct":false,"misconception_token":"misjudges-evidence"},{"text":"It is strong because history later showed that railroads won out.","is_correct":false,"misconception_token":"outcome-bias"}]$q$::jsonb, $q$It is weak because other towns' choices do not show which option suits Brennick.$q$, $q$That neighbors chose railroads is an appeal to popularity, and it says nothing about Brennick's own costs or needs, which is the weakness Pollock points out. The later success of railroads does not make the reasoning sound at the time, as the historians' debate suggests.$q$, 'draft', '4a94ef71-c422-5acd-9e2a-57dc871d959e')
