  ('27280ebf-b66e-5239-a633-ae7907699c25', null, (select id from public.skills where slug = 'read-g11-argument-evidence'), null, 'hard',
   $q$Which statement best evaluates the author's move from the Lindqvist's experience to a recommendation for every museum?$q$, $q$[{"text":"It is reasonable because the Lindqvist's attendance more than doubled.","is_correct":false,"misconception_token":"overstates-evidence"},{"text":"It is reasonable because the author answers every critic in the passage.","is_correct":false,"misconception_token":"misjudges-evidence"},{"text":"It generalizes from one museum whose plan depended on a large pledge others may lack.","is_correct":true},{"text":"It is weak only because the author never says what admission used to cost.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$It generalizes from one museum whose plan depended on a large pledge others may lack.$q$, $q$One case cannot show what will happen everywhere, especially when the Lindqvist's survival relied on a $1.5 million foundation pledge. The former $18 fee is stated in the first paragraph, so the choice saying the author never gives the old price misreads the text.$q$, 'draft', '641390e0-ee28-5d5a-a030-4a90a6d0fe11')
