  ('4800f40b-298b-5058-b1d5-6f876ad3afc0', null, (select id from public.skills where slug = 'read-g11-authors-purpose'), null, 'easy',
   $q$What is the speaker's main purpose?$q$, $q$[{"text":"To persuade the committee to remove the bike lanes and the renovated fountain","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"To explain how benches are designed and built for use on city sidewalks","is_correct":false,"misconception_token":"too-narrow"},{"text":"To persuade the committee to add many more benches to the downtown plan","is_correct":true},{"text":"To complain that the lighting design in the current draft is not beautiful","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$To persuade the committee to add many more benches to the downtown plan$q$, $q$The speaker says, "It includes six benches along eleven blocks. I am here to ask for sixty." The speaker praises the lighting design and never asks to cut the bike lanes or fountain.$q$, 'draft', '4b8fd98d-207e-59f4-8602-08897cb27068')
